def count_paths(N):
    # N is the dimension (4 for 4x4)
    board = {}
    index = 1
    for r in range(N):
        for c in range(N):
            board[(r, c)] = index
            index += 1

    # Memoization for path counts N(C)
    memo = {}

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                neighbors.append((nr, nc))
        return neighbors

    def calculate_N(r, c):
        if (r, c) in memo:
            return memo[(r, c)]

        current_value = board[(r, c)]

        # N(C) = 1 + sum(N(C')) for neighbors C' with V(C') > V(C)
        sum_N_prime = 0

        neighbors = get_neighbors(r, c)
        for nr, nc in neighbors:
            neighbor_value = board[(nr, nc)]
            if neighbor_value > current_value:
                sum_N_prime += calculate_N(nr, nc)

        result = 1 + sum_N_prime
        memo[(r, c)] = result
        return result

    # 1. Identify Starting Fields S
    S = []
    for r in range(N):
        for c in range(N):
            current_value = board[(r, c)]
            is_starting_field = True
            neighbors = get_neighbors(r, c)

            for nr, nc in neighbors:
                neighbor_value = board[(nr, nc)]
                if neighbor_value < current_value:
                    is_starting_field = False
                    break

            if is_starting_field:
                S.append((r, c))

    # 2. Calculate Total Paths
    total_paths = 0
    for r, c in S:
        total_paths += calculate_N(r, c)

    print(f"Board configuration (lexicographical):")
    for r in range(N):
        row = [str(board[(r, c)]) for c in range(N)]
        print(" ".join(row))
    print(f"Starting Fields S: {S}")
    print(f"Total number of good paths (Total Paths): {total_paths}")

N = 4
count_paths(N)
